solution:
use xiom.io;
interface Readable { fn read(&self) -> Str; }
interface Writable { fn write(&mut self, data: Str); }

type Note {
  text: Str;
}

fn Note.read(&self) -> Str {
  self.text.clone()
}

fn Note.write(&mut self, data: Str) {
  self.text = data;
}

fn save_document[T: Readable + Writable](doc: &mut T) {
  let content = doc.read();
  doc.write(content);
}

fn main() -> Int {
  let mut note = Note{ text: "Hello" };
  save_document(&mut note);
  io.println(note.text.to_str());
  return 0;
}
